var D={"NICK": {"INTJ": "말하기 전에 결론 나 있는 타입", "INTP": "정신 차려 보면 검색 삼매경 타입", "ENTJ": "그럼 내가 정할게 타입", "ENTP": "'근데 반대로'가 입버릇인 타입", "INFJ": "말 안 해도 알아채는 타입", "INFP": "머릿속이 영화관인 타입", "ENFJ": "자꾸 챙겨 주게 되는 타입", "ENFP": "설렘이 최우선인 타입", "ISTJ": "마감보다 먼저 내는 타입", "ISFJ": "어느새 움직이고 있는 타입", "ESTJ": "일단 계획표부터 짜는 타입", "ESFJ": "어느새 총무 맡는 타입", "ISTP": "설명보다 먼저 만져 보는 타입", "ISFP": "좋아! 로 고르는 타입", "ESTP": "생각하기 전에 움직이는 타입", "ESFP": "분위기 타서 정해 버리는 타입"}, "ARUARU": {"INTJ": ["회의 중에 이미 결론은 나 있는데 말을 안 해요", "계획이 틀어지면 속으로 꽤 짜증 나요", "스몰토크보다 본론으로 들어가고 싶어요", "혼자서 끝낼 수 있는 일이 제일 빨라요", "'그냥'으로 정하는 사람이 이해가 안 돼요"], "INTP": ["검색하다 보면 전혀 다른 늪에 빠져 있어요", "'그거 정의가 뭔데?'라고 묻고 싶어져요", "관심 없는 건 놀랄 만큼 머리에 안 들어와요", "밤이 되면 머리가 더 잘 돌아가요", "설명이 자꾸 길어져요"], "ENTJ": ["결론 안 나는 회의를 못 견뎌요", "정신 차려 보면 진행을 맡고 있어요", "쓸데없는 시간이 제일 싫어요", "목표가 있을수록 불타올라요", "누가 기대면 거절을 못 해요"], "ENTP": ["떠오른 걸 일단 말하고 나서 생각해요", "'근데 반대로'로 이야기를 키워요", "금방 질려요", "토론은 싸움이 아니라 놀이예요", "새 앱은 일단 깔고 봐요"], "INFJ": ["말하기 전에 상대 컨디션이 안 좋은 걸 알아채요", "속마음은 좀처럼 안 보여 줘요", "사람 많은 곳에 다녀오면 혼자 있고 싶어요", "의미 없는 일에는 시간을 못 써요", "상담은 자주 받는데 정작 나는 상담 안 해요"], "INFP": ["머릿속으로 대화 리허설을 해요", "좋아하는 이야기가 나오면 갑자기 말이 많아져요", "현실적인 이야기를 하면 지쳐요", "예전에 들은 말을 몇 년이고 기억해요", "내 안의 정답은 절대 못 양보해요"], "ENFJ": ["모두의 표정을 살피면서 말해요", "부탁받으면 거절을 못 해요", "내 일은 늘 뒷전이에요", "분위기가 조용하면 화제를 꺼내요", "남이 성장하면 내 일처럼 기뻐요"], "ENFP": ["대화가 세 단계씩 점프해요", "하고 싶은 게 너무 많아서 정체 중이에요", "마감 직전에 방 청소를 하게 돼요", "처음 만난 사람과도 금방 친해져요", "질리면 한순간에 식어요"], "ISTJ": ["일정은 미리미리 끝내 둬요", "규칙 안 지키는 사람이 신경 쓰여요", "물건마다 제자리가 정해져 있어요", "갑작스러운 변경에 은근히 당황해요", "한번 정한 방식은 바꾸고 싶지 않아요"], "ISFJ": ["먼저 알아채고 먼저 움직여요", "'괜찮아'라고 하면서 참고 있어요", "사람들 취향을 기억해요", "눈에 띄는 역할은 하기 싫어요", "누가 기대 오면 기뻐요"], "ESTJ": ["일단 순서부터 정해요", "애매한 지시에 짜증 나요", "시간 약속에 엄격해요", "맡은 일은 끝까지 다 해내요", "가까운 사람한테는 말투가 세져요"], "ESFJ": ["정신 차려 보면 모임 총무를 하고 있어요", "모두의 컨디션이나 기분이 신경 쓰여요", "혼자 있는 시간이 길면 외로워요", "기념일을 잘 기억해요", "미움받고 있지 않은지 확인하고 싶어져요"], "ISTP": ["설명서보다 먼저 만져 봐요", "단톡방은 읽기만 해요", "쓸데없는 대화가 힘들어요", "고장 나면 일단 내가 고쳐요", "흥미가 떨어지면 갑자기 손이 멈춰요"], "ISFP": ["느낌이 안 오는 건 못 골라요", "유행보다 내가 좋아하는 게 우선", "재촉받는 게 힘들어요", "사진이나 배치에 신경 써요", "화는 안 내지만 속으로는 안 물러서요"], "ESTP": ["생각보다 몸이 먼저 움직여요", "지루한 게 제일 싫어요", "분위기를 금방 파악해요", "계획보다 현장 대응이 특기예요", "뒷정리는 나중으로 미뤄요"], "ESFP": ["분위기 따라 약속을 잡아요", "사진 찍는 걸 좋아해요", "우울해도 자고 나면 회복돼요", "분위기 메이커 담당이 되기 쉬워요", "단조로운 작업은 오래 못 해요"]}, "TCOMPAT": {"INTJ": {"m": "ENTP", "why": "전략에 새로운 바람을 불어넣어 주는 아이디어 뱅크예요."}, "ENTP": {"m": "INTJ", "why": "번뜩이는 생각을 탄탄한 계획으로 만들어 줘요."}, "INTP": {"m": "ENTJ", "why": "생각을 형태로 만들어 앞으로 밀고 나가 주는 실행가예요."}, "ENTJ": {"m": "INTP", "why": "참신한 시선으로 발상을 넓혀 주는 브레인이에요."}, "INFJ": {"m": "ENFP", "why": "속에 품은 마음을 밝게 끌어내 줘요."}, "ENFP": {"m": "INFJ", "why": "펼쳐 놓은 꿈을 조용히 깊게 만들어 주는 상대예요."}, "INFP": {"m": "ENFJ", "why": "이상을 진심으로 응원해 주는 든든한 길잡이예요."}, "ENFJ": {"m": "INFP", "why": "당신의 다정함을 필요로 해 주는 순수한 사람이에요."}, "ISTJ": {"m": "ESTP", "why": "착실한 당신에게 자극과 행동력을 줘요."}, "ESTP": {"m": "ISTJ", "why": "넘치는 기세를 단단한 토대로 받쳐 주는 상대예요."}, "ISFJ": {"m": "ESFP", "why": "성실함을 확 밝게 만들어 주는 분위기 메이커예요."}, "ESFP": {"m": "ISFJ", "why": "즐거움을 살며시 받쳐 주는 든든한 존재예요."}, "ISTP": {"m": "ESTJ", "why": "당신의 실력을 살릴 무대를 마련해 줘요."}, "ESTJ": {"m": "ISTP", "why": "결정적인 순간에 믿을 수 있는 냉정한 실력자예요."}, "ISFP": {"m": "ESFJ", "why": "마이페이스인 당신을 따뜻하게 받쳐 줘요."}, "ESFJ": {"m": "ISFP", "why": "꾸밈없는 감성으로 마음을 편하게 해 주는, 있는 그대로의 상대예요."}}, "GAP_USE": {"IE": {"h": "充電｜内向き → 外向き に変身", "t": "ほんとうは一人で充電する人が、人と関わる力を装備した状態。人前のあとにどっと疲れるのは、気のせいじゃなく装備の重さです。予定のあとに“ひとり時間”を確保すると、回復が一気に速くなります。"}, "EI": {"h": "充電｜外向き → 内向き に変身", "t": "ほんとうは人といて充電する人が、今はひとりモード。最近なんとなく元気が出ないなら、原因は“人との時間の不足”かも。気のおけない人と会う予定をひとつ入れるだけで、驚くほど復活します。"}, "SN": {"h": "見方｜現実派 → 直感派 に変身", "t": "地に足のついた現実派が、ひらめきで動く力を獲得。アイデアが浮かんでも「ほんとに大丈夫？」と不安になるのは、素の現実感覚が生きている証拠。ひらめきを素の現実力で検算すれば最強です。"}, "NS": {"h": "見方｜直感派 → 現実派 に変身", "t": "本来ひらめき型のあなたが、現実的にふるまう力を装備。ときどき無性に“夢の話”がしたくなるのは、素の顔の呼吸です。空想の時間はサボりじゃなく、あなたの充電です。"}, "TF": {"h": "決め方｜論理派 → 共感派 に変身", "t": "本来スジで決める人が、人に合わせて受け止める力を獲得。合わせたあとに「本音を言えばよかった」とモヤモヤしやすいタイプ。大事な決断だけは、素のロジックに戻って決めると後悔しません。"}, "FT": {"h": "決め方｜共感派 → 論理派 に変身", "t": "本来は気持ちで決める人が、冷静に判断する鎧を装備。クールに見えて、内側では感情がちゃんと動いています。ときどき“好きか嫌いか”だけで選ぶと、心の疲れがすっと取れます。"}, "JP": {"h": "動き方｜計画派 → 自由派 に変身", "t": "本来は計画派なのに、流れに乗る柔軟さを獲得。自由に見えて、心のどこかで“決まっていない不安”を感じやすい人です。ざっくりでも予定を置くと、安心して楽しめます。"}, "PJ": {"h": "動き方｜自由派 → 計画派 に変身", "t": "本来は自由派なのに、段取りの力を身につけた人。きっちりこなせるのに、たまに全部投げ出したくなるのはこのせい。“予定のない日”を先にカレンダーに入れておくのがコツです。"}}, "COLOR": {"INTJ": {"name": "深い藍", "hex": "#27406B", "line": "夜明け前の藍。静かに全体を見渡す色。"}, "INTP": {"name": "アイスブルー", "hex": "#79B6D9", "line": "澄んだ氷の青。思考が透きとおる色。"}, "ENTJ": {"name": "クリムゾン", "hex": "#C8102E", "line": "燃える深紅。目標へ突き進む色。"}, "ENTP": {"name": "エレクトリックオレンジ", "hex": "#FF6A2C", "line": "火花のオレンジ。刺激を生み出す色。"}, "INFJ": {"name": "アメジスト", "hex": "#6A4C93", "line": "神秘の紫。静かな理想を秘めた色。"}, "INFP": {"name": "ラベンダー", "hex": "#B79CE0", "line": "淡い藤色。やさしく夢みる色。"}, "ENFJ": {"name": "コーラル", "hex": "#FF8364", "line": "夕日のコーラル。人を照らすあたたかな色。"}, "ENFP": {"name": "ビビッドイエロー", "hex": "#FFD23F", "line": "弾ける黄色。その場を明るくする色。"}, "ISTJ": {"name": "ディープグリーン", "hex": "#2F6B5E", "line": "落ち着いた深緑。ぶれない芯の色。"}, "ISFJ": {"name": "ソフトピーチ", "hex": "#F4C9A8", "line": "やわらかな桃色。そっと包む色。"}, "ESTJ": {"name": "ロイヤルブルー", "hex": "#2457C5", "line": "堂々のブルー。頼れる芯の色。"}, "ESFJ": {"name": "ウォームローズ", "hex": "#F77FA1", "line": "あたたかな薔薇色。みんなを和ませる色。"}, "ISTP": {"name": "ガンメタル", "hex": "#8C97A0", "line": "クールな銀。無駄のない色。"}, "ISFP": {"name": "セージグリーン", "hex": "#8FBF9F", "line": "やさしい若草。自然体でいられる色。"}, "ESTP": {"name": "ネオンレッド", "hex": "#FF3B30", "line": "躍動の赤。動くほど光る色。"}, "ESFP": {"name": "ホットピンク", "hex": "#FF2E9A", "line": "華やぐマゼンタ。主役のオーラの色。"}}, "URA": {"INTJ": "じつは、頭の中では何手も先まで読んで、もう一人で完結している。", "INTP": "じつは、「なんで？」が止まらず、夜中に関係ない調べ物で時間が溶ける。", "ENTJ": "じつは、任されないとソワソワ。仕切りたくて手がうずうずしている。", "ENTP": "じつは、思いつきを口に出してから「どうしよう」と考えはじめる。", "INFJ": "じつは、ニコニコしながら相手の本音を静かに見抜いている。", "INFP": "じつは、頭の中で壮大なストーリーが毎日上映されている。", "ENFJ": "じつは、みんなを気づかうあまり、自分のことは後回しにしがち。", "ENFP": "じつは、やりたいこと多すぎて、半分は途中で次へ移っている。", "ISTJ": "じつは、段取りを乱す人に、心の中でこっそりイラッとしている。", "ISFJ": "じつは、「大丈夫」と言いながら、いちばん我慢している。", "ESTJ": "じつは、ゆるい計画を見ると、つい口を出したくてうずうず。", "ESFJ": "じつは、嫌われてないかな…と、こっそり空気を確認している。", "ISTP": "じつは、興味ないことには無関心。好きなことには無限に集中する。", "ISFP": "じつは、マイペースに見えて、譲れない美学はかなり頑固。", "ESTP": "じつは、退屈がいちばん苦手。刺激がないと自分で作りにいく。", "ESFP": "じつは、楽しそうにしながら、場の空気をいちばん読んでいる。"}, "QUOTE": {"INTJ": ["그래서 최종 목표가 뭐야?", "그거 더 효율적인 방법 있어", "예상한 범위야"], "INTP": ["그건 정의하기 나름이지", "잠깐 찾아볼게", "논리는 알겠어. 근데 왜?"], "ENTJ": ["결론부터 말하면", "누가, 언제까지 해?", "맡겨. 내가 정해 둘게"], "ENTP": ["반대로 말이야,", "그거 재밌지 않아?", "일부러 반대 의견 말해 볼게"], "INFJ": ["진짜로는 어떻게 하고 싶어?", "왠지 알고 있었어", "그거 그 사람이 상처받지 않을까"], "INFP": ["그게 나다운 걸까", "조금 생각해 볼게", "좋아하니까, 로 충분하지 않아?"], "ENFJ": ["다들 어떻게 생각해?", "괜찮아, 같이 하자", "너라면 할 수 있어"], "ENFP": ["그거 완전 좋다!", "방금 생각난 건데", "일단 해 보자!"], "ISTJ": ["지난번엔 이렇게 했어요", "확인하고 답할게요", "규칙이라서요"], "ISFJ": ["괜찮아? 무리하는 거 아니야?", "내가 해 둘게", "다들 좋으면 나도 좋아"], "ESTJ": ["일단 일정부터 정하자", "그거 마감이 언제야?", "규칙은 규칙이니까"], "ESFJ": ["다 같이 하자", "간식 사 왔어", "그거 그 친구한테 미안하지 않아?"], "ISTP": ["해 보면 알아", "뭐, 아무거나", "잠깐 줘 봐. 고쳐 줄게"], "ISFP": ["그냥 좋아 보여서", "내 페이스대로 할게", "말로 하기 어렵네"], "ESTP": ["일단 가 보자", "생각보다 움직이는 게 빨라", "어떻게든 돼"], "ESFP": ["재밌으면 됐지!", "지금부터 어때?", "사진 찍자!"]}};
